do {                                                                         \
    if (nghttp2_failmalloc && nghttp2_nmalloc >= nghttp2_failstart) {          \
      return NULL;                                                             \
    }                                                                          \
    if (nghttp2_countmalloc) {                                                 \
      ++nghttp2_nmalloc;                                                       \
    }                                                                          \
  } while (0)

